// Types next-intl's `t()`, `useTranslations()` and `getTranslations()` keys from the English catalog
// (`Messages`, generated by `pnpm i18n:types` in @causedeck/i18n) and the locale union.
import type { Locale, Messages } from '@causedeck/i18n';

declare module 'next-intl' {
  interface AppConfig {
    Locale: Locale;
    Messages: Messages;
  }
}
